@pytest.mark.asyncio
async def test_driver_skips_duplicate_review_pause_for_announced_ids() -> None:
    """aoub: graph-driven RUN_PAUSED must not be re-emitted on wait timeout."""
    case = replay_bypass_case()
    case.run_context.announced_pause_control_ids.add("field-email")
    timeout = InterruptWaitTimedOut(
        timeout_seconds=60.0, pending_control_ids=("field-email",)
    )

    await driver._emit_review_pause(case.config, case.run_context, timeout)

    assert case.recorder.events == [], (
        "a pause already announced by the graph-driven interrupt must not be ",
        "re-emitted when the interrupt wait times out"
    )


@pytest.mark.asyncio
async def test_driver_emits_review_pause_for_unannounced_ids() -> None:
    """aoub: a timeout for never-announced controls still emits RUN_PAUSED."""
    case = replay_bypass_case()
    timeout = InterruptWaitTimedOut(
        timeout_seconds=60.0, pending_control_ids=("field-phone",)
    )

    await driver._emit_review_pause(case.config, case.run_context, timeout)

    assert len(case.recorder.events) == 1, (
        "a timeout without a prior graph-driven announcement must surface the pause"
    )
    [event] = case.recorder.events
    assert getattr(event, "pending_control_ids", []) == ["field-phone"], (
        "the unannounced pause event must carry its pending control ids"
    )
